<?php
$qtext=trim((string)($_GET['q']??''));$sql='SELECT l.*,u.name user_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id WHERE 1=1';$params=[];if($qtext!==''){$sql.=' AND (l.action LIKE ? OR l.description LIKE ? OR u.name LIKE ?)';$params[]="%$qtext%";$params[]="%$qtext%";$params[]="%$qtext%";}$sql.=' ORDER BY l.created_at DESC LIMIT 500';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
?>
<div class="page-heading"><div><div class="eyebrow">Security & traceability</div><h1>Activity logs</h1><p>Review sign-ins and important business record changes.</p></div></div>
<div class="card"><div class="card-body border-bottom"><form class="search-box"><input type="hidden" name="page" value="logs"><i class="bi bi-search"></i><input class="form-control" name="q" value="<?=h($qtext)?>" placeholder="Search user, action or description"></form></div><div class="table-responsive"><table class="table"><thead><tr><th>User</th><th>Action</th><th>Description</th><th>IP address</th><th>Date & time</th></tr></thead><tbody><?php if(!$rows)echo table_empty(5);foreach($rows as $r):?><tr><td class="fw-semibold"><?=h($r['user_name']??'System / removed user')?></td><td><span class="badge text-bg-light"><?=h($r['action'])?></span></td><td><?=h($r['description'])?></td><td class="small-muted"><?=h($r['ip_address']??'—')?></td><td><?=date('M j, Y g:i:s A',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><div class="card-body small-muted">Most recent 500 activity events. Log records are retained for accountability.</div></div>
